public class Jit {
    static long trabajo(int n) {
        long total = 0;
        for (int i = 0; i < n; i++) total += (long) i * i % 1000;
        return total;
    }
    public static void main(String[] args) {
        for (int ronda = 1; ronda <= 5; ronda++) {
            long t0 = System.nanoTime();
            long r = trabajo(100_000_000);
            double s = (System.nanoTime() - t0) / 1e9;
            System.out.printf("ronda %d: %.3f s (resultado %d)%n", ronda, s, r);
        }
    }
}

import java.util.*;

public class Entregas {
    record Entrega(String zona, int bultos, boolean entregado) {}

    public static void main(String[] args) {
        List<Entrega> entregas = List.of(
            new Entrega("Palermo", 12, true),
            new Entrega("Palermo", 8, false),
            new Entrega("Caballito", 15, true),
            new Entrega("Belgrano", 6, true),
            new Entrega("Caballito", 9, true),
            new Entrega("Belgrano", 4, false)
        );

        Map<String, int[]> porZona = new HashMap<>();
        for (Entrega e : entregas) {
            int[] acum = porZona.computeIfAbsent(e.zona(), z -> new int[2]);
            acum[0] += e.bultos();
            if (!e.entregado()) acum[1] += e.bultos();
        }

        porZona.entrySet().stream()
            .sorted((x, y) -> y.getValue()[0] - x.getValue()[0])
            .forEach(par -> System.out.printf("%-10s %3d bultos - %2d sin entregar (%.0f %%)%n",
                par.getKey(), par.getValue()[0], par.getValue()[1],
                100.0 * par.getValue()[1] / par.getValue()[0]));
    }
}

data class Entrega(val zona: String, val bultos: Int, val entregado: Boolean)

fun main() {
    val entregas = listOf(
        Entrega("Palermo", 12, true),
        Entrega("Palermo", 8, false),
        Entrega("Caballito", 15, true),
        Entrega("Belgrano", 6, true),
        Entrega("Caballito", 9, true),
        Entrega("Belgrano", 4, false),
    )

    entregas
        .groupBy { it.zona }
        .mapValues { (_, lista) ->
            val total = lista.sumOf { it.bultos }
            val pendientes = lista.filter { !it.entregado }.sumOf { it.bultos }
            total to pendientes
        }
        .entries.sortedByDescending { it.value.first }
        .forEach { (zona, par) ->
            val (total, pendientes) = par
            println("%-10s %3d bultos - %2d sin entregar (%.0f %%)".format(zona, total, pendientes, 100.0 * pendientes / total))
        }
}

