import kotlinx.coroutines.*
import kotlin.system.measureTimeMillis

suspend fun consultarEstado(pedido: Int): String {
    delay(1000)                      // espera 1 s SIN bloquear el hilo
    return "pedido $pedido: en camino"
}

fun main() = runBlocking {
    val ms = measureTimeMillis {
        val respuestas = (1..10_000).map { n ->
            async { consultarEstado(n) }
        }.awaitAll()
        println(respuestas.first())
        println(respuestas.last())
        println("respuestas: ${respuestas.size}")
    }
    println("tardó unos ${ms / 100 / 10.0} s con 10.000 corrutinas esperando a la vez")
    println("hilos de Java vivos: ${Thread.getAllStackTraces().keys.size}")
}

import java.util.*;

public class Hilos {
    static void esperar() {
        try { Thread.sleep(1000); } catch (InterruptedException e) { }
    }

    static double correr(boolean virtuales, int cantidad) throws Exception {
        long t0 = System.nanoTime();
        List<Thread> hilos = new ArrayList<>();
        for (int i = 0; i < cantidad; i++) {
            Thread h = virtuales ? Thread.ofVirtual().start(Hilos::esperar)
                                 : Thread.ofPlatform().start(Hilos::esperar);
            hilos.add(h);
        }
        for (Thread h : hilos) h.join();
        return (System.nanoTime() - t0) / 1e9;
    }

    public static void main(String[] args) throws Exception {
        int n = 10_000;
        System.out.printf("%d hilos de la plataforma esperando 1 s: %.2f s%n", n, correr(false, n));
        System.out.printf("%d hilos virtuales esperando 1 s:        %.2f s%n", n, correr(true, n));
    }
}
